// Fixtures for web/ui/sound.mjs, shared by test/uisound.test.mjs and the
// shots gallery (scripts/ui-shots/gallery/sound.html, which is generated from
// these so it can never drift from what the renderers draw):
//
//   node test/fixtures/uisound.mjs --write
import * as S from '../../web/ui/sound.mjs';
import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

export const SOUND = {
  octaveUnsure: { bpm: 174, bpmAlt: 87, bpmConf: 0.42, camelot: '8A', key: 'A minor', keyConf: 0.81, energy: 0.78, voice: 'instrumental',
                  styles: [['Drum n Bass', 0.61], ['Jungle', 0.22]], sections: [['Drum n Bass', 'Jungle'], ['Drum n Bass']] },
  hybrid: { bpm: 136, camelot: '4A', key: 'F minor', energy: 0.7, voice: 'vocal', hybrid: true,
            styles: [['Bassline', 0.41], ['Electronic---UK Garage', 0.3], ['Donk', 0.18]],
            sections: [['Bassline', 'Speed Garage'], ['Bassline'], ['Donk', 'Hard House'], ['Donk']] },
  oneStyle: { sections: [['Deep House'], ['Deep House'], ['Deep House']] },
  wide: { sections: [['Techno'], ['Ambient'], ['Hip Hop'], ['House'], ['Dubstep'], ['Shoegaze'], ['Trance'], ['Pop']] },
};

export const EVIDENCE = {
  tagsOnly: { tags: 1 },
  mixed: { tags: 0.5, history: 0.3, sound: 0.2 },
  all: { tags: 0.35, history: 0.25, sound: 0.25, learned: 0.15 },
  soundLed: { tags: 0.1, sound: 0.7, learned: 0.2 },
};

export const PROFILE = {
  b2: { heard: 14, members: 40, styles: [['Bassline', 0.57], ['UK Garage', 0.29], ['Speed Garage', 0.14]] },
  full: { heard: 38, members: 40, bpm: [132, 140], energy: [0.55, 0.85], styles: [['Drum n Bass', 0.6], ['Jungle', 0.3]] },
  one: { heard: 1, members: 1 },
};

export const LISTEN = {
  running: { state: 'running', done: 412, total: 1980, heard: 380, missed: { NOT_ON_DEEZER: 21, NO_PREVIEW: 9, NO_ISRC: 2 } },
  starting: { state: 'running', done: 0, total: 0, heard: 0, missed: {} },
  paused: { state: 'paused', done: 600, total: 1980, reason: 'waiting for Wi-Fi', heard: 560, missed: { NOT_ON_DEEZER: 40 } },
  stopped: { state: 'paused', done: 12, total: 1980, reason: 'stopped', heard: 12, missed: {} },
  done: { state: 'done', done: 1980, total: 1980, heard: 1802, missed: { NOT_ON_DEEZER: 120, NO_PREVIEW: 40, IDENTITY: 12, TOO_SHORT: 4, FAILED: 2 } },
  allMiss: { state: 'done', done: 40, total: 40, heard: 0, missed: { NO_ISRC: 3, NOT_ON_DEEZER: 25, NO_PREVIEW: 12 } },
  offWithHistory: { state: 'off', done: 0, total: 0, heard: 220, missed: {} },
  off: { state: 'off', done: 0, total: 0, heard: 0, missed: {} },
};

const sec = (title, html) => `<h2>${title}</h2>\n<div class="rowx" style="flex-direction:column;align-items:stretch;gap:14px">\n${html}\n</div>\n`;
const item = (name, html) => `<div><div class="sub mono" style="font-size:11px;margin-bottom:4px">${name}</div>${html}</div>`;

/** The gallery fragment: every component on every fixture. */
export function galleryHTML() {
  const art = vm => `<div style="width:132px"><div style="width:132px;height:132px;border-radius:8px;background:var(--surface-3)"></div>${S.sectionStrip(vm)}</div>`;
  return `<!-- Generated by test/fixtures/uisound.mjs --write. Do not edit by hand. -->
<h1 style="font-family:var(--display);margin:0 0 4px">Sound layer</h1>
<p class="lede">Every renderer in web/ui/sound.mjs on its fixtures. With no audio data each one draws nothing.</p>
${sec('Section strip under the artwork', `<div class="rowx" style="align-items:flex-start;gap:18px">${Object.entries(SOUND).map(([k, v]) => item(k, art(v))).join('')}</div>`)}
${sec('Sound chip (WP-D4) and strip, in a track row', Object.entries(SOUND).slice(0, 2).map(([k, v]) =>
    item(k, `<div class="row"><div class="main"><div class="ttl">A track</div><div class="sub">${S.soundChip(v) || '<span class="mono">(soundChip lands with WP-D4)</span>'}</div>${S.sectionStrip(v)}</div></div>`)).join('\n'))}
${sec('Confidence band', `<div class="rowx">${[['HIGH', 0.91], ['LIKELY', 0.64], ['AMBIGUOUS', 0.38], ['HIGH'], ['medium'], ['low']].map(([b, p]) => S.bandChip(b, p)).join('')}</div>`)}
${sec('Evidence badges', Object.entries(EVIDENCE).map(([k, v]) => item(k, `<div class="rowx">${S.bandChip('LIKELY', 0.7)}${S.evidenceBadges(v)}</div>`)).join('\n'))}
${sec('Playlist sound profile', Object.entries(PROFILE).map(([k, v]) =>
    item(k, `<div class="row axrow"><div class="main"><div class="ttl">A playlist</div><div class="sub"><span class="mono">40 tracks</span></div>${S.profileRow(v)}</div></div>`)).join('\n'))}
${sec('Listening pill', `<div class="rowx">${Object.entries(LISTEN).map(([k, v]) => S.listenPill(v)).filter(Boolean).join('')}</div>`)}
${sec('Listening card body', Object.entries(LISTEN).filter(([, v]) => S.listenCard(v)).map(([k, v]) =>
    item(k, `<div class="card" style="padding:14px 16px">${S.listenCard(v)}</div>`)).join('\n'))}
${sec('Couldn’t be heard (open)', item('done', S.missedList(LISTEN.done).replace('<details class="smiss">', '<details class="smiss" open>')))}
`;
}

if (process.argv[1] === fileURLToPath(import.meta.url) && process.argv.includes('--write')) {
  writeFileSync(new URL('../../scripts/ui-shots/gallery/sound.html', import.meta.url), galleryHTML());
  console.log('wrote scripts/ui-shots/gallery/sound.html');
}
